sql.query:
SELECT * FROM grafana_api.ds_query(dsUid := '$ds_prometheus$', targetsJson := '[{"datasource":{"type":"prometheus","uid":"$ds_prometheus$"},"exemplar":false,"expr":"(
  (node_filesystem_size_bytes{instance="$node$", job="$job$", mountpoint="/", fstype!="rootfs"}
   - node_filesystem_avail_bytes{instance="$node$", job="$job$", mountpoint="/", fstype!="rootfs"})
  / node_filesystem_size_bytes{instance="$node$", job="$job$", mountpoint="/", fstype!="rootfs"}
) * 100
","format":"time_series","instant":true,"range":false,"refId":"A"}]', from := '$time.from_ms$', to := '$time.to_ms$')
